import Foundation
import CRestoreSQLite
public actor CompoundRestoreQueue{
 private var db:OpaquePointer?
 private let transient=unsafeBitCast(-1,to:sqlite3_destructor_type.self)
 public init(url:URL)throws{let root=url.deletingLastPathComponent();try FileManager.default.createDirectory(at:root,withIntermediateDirectories:true,attributes:[.posixPermissions:0o700]);var excluded=root;var values=URLResourceValues();values.isExcludedFromBackup=true;try excluded.setResourceValues(values)
 #if os(iOS)
 try FileManager.default.setAttributes([.protectionKey:FileProtectionType.completeUntilFirstUserAuthentication],ofItemAtPath:root.path)
 #endif
 guard sqlite3_open_v2(url.path,&db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_FULLMUTEX,nil)==SQLITE_OK else{throw RestoreFailure.storage};sqlite3_busy_timeout(db,5000);guard sqlite3_exec(db,"PRAGMA journal_mode=WAL;PRAGMA synchronous=FULL;CREATE TABLE IF NOT EXISTS compound(id TEXT PRIMARY KEY,account TEXT NOT NULL,library TEXT NOT NULL,manifest TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL,record BLOB NOT NULL);CREATE INDEX IF NOT EXISTS compound_page ON compound(account,library,id);CREATE UNIQUE INDEX IF NOT EXISTS compound_active ON compound(account,library,manifest) WHERE state NOT IN('RESTORED','CANCELLED','FAILED_PERMANENT','RECONCILE_REQUIRED');",nil,nil,nil)==SQLITE_OK else{throw RestoreFailure.storage};try FileManager.default.setAttributes([.posixPermissions:0o600],ofItemAtPath:url.path)}
 deinit{sqlite3_close(db)}
 private func stmt(_ sql:String)throws->OpaquePointer{var s:OpaquePointer?;guard sqlite3_prepare_v2(db,sql,-1,&s,nil)==SQLITE_OK,let s else{throw RestoreFailure.storage};return s}
 private func bind(_ v:String,_ s:OpaquePointer,_ n:Int32){_=v.withCString{sqlite3_bind_text(s,n,$0,-1,transient)}}
 private func data(_ r:CompoundRestoreRecord,_ s:OpaquePointer,_ n:Int32)throws{let d=try JSONEncoder().encode(r);_=d.withUnsafeBytes{sqlite3_bind_blob(s,n,$0.baseAddress,Int32(d.count),transient)}}
 private func decode(_ s:OpaquePointer)throws->CompoundRestoreRecord{guard let p=sqlite3_column_blob(s,0) else{throw RestoreFailure.storage};return try JSONDecoder().decode(CompoundRestoreRecord.self,from:Data(bytes:p,count:Int(sqlite3_column_bytes(s,0))))}
 public func insert(_ r:CompoundRestoreRecord,restoreAgain:Bool=false)throws{guard r.plan.valid,r.plan.reconstructable,r.state == .queued,r.revision==0 else{throw RestoreFailure.unsupported};let prior=try stmt("SELECT 1 FROM compound WHERE account=? AND library=? AND manifest=? AND state IN('RESTORED','RECONCILE_REQUIRED') LIMIT 1");defer{sqlite3_finalize(prior)};for(n,v)in [r.account.uuidString,r.library.uuidString,r.plan.manifest.id.uuidString].enumerated(){bind(v,prior,Int32(n+1))};if sqlite3_step(prior)==SQLITE_ROW && !restoreAgain{throw RestoreFailure.duplicate};let s=try stmt("INSERT INTO compound VALUES(?,?,?,?,?,0,?)");defer{sqlite3_finalize(s)};for(n,v)in [r.id.uuidString,r.account.uuidString,r.library.uuidString,r.plan.manifest.id.uuidString,r.state.rawValue].enumerated(){bind(v,s,Int32(n+1))};try data(r,s,6);guard sqlite3_step(s)==SQLITE_DONE else{throw RestoreFailure.duplicate}}
 public func read(_ id:UUID)throws->CompoundRestoreRecord?{let s=try stmt("SELECT record FROM compound WHERE id=?");defer{sqlite3_finalize(s)};bind(id.uuidString,s,1);let result=sqlite3_step(s);if result==SQLITE_DONE{return nil};guard result==SQLITE_ROW else{throw RestoreFailure.storage};return try decode(s)}
 public func page(account:UUID,library:UUID,after:UUID?=nil,limit:Int=100)throws->[CompoundRestoreRecord]{guard (1...1000).contains(limit) else{throw RestoreFailure.storage};let s=try stmt("SELECT record FROM compound WHERE account=? AND library=? AND id>? ORDER BY id LIMIT ?");defer{sqlite3_finalize(s)};for(n,v)in [account.uuidString,library.uuidString,after?.uuidString ?? ""].enumerated(){bind(v,s,Int32(n+1))};sqlite3_bind_int(s,4,Int32(limit));var rows:[CompoundRestoreRecord]=[];while true{let result=sqlite3_step(s);if result==SQLITE_DONE{return rows};guard result==SQLITE_ROW else{throw RestoreFailure.storage};rows.append(try decode(s))}}
 @discardableResult public func save(_ r:CompoundRestoreRecord,completedIdentifier:String?=nil)throws->CompoundRestoreRecord{guard let old=try read(r.id),old.revision==r.revision,old.account==r.account,old.library==r.library,old.fileIDs==r.fileIDs,old.plan==r.plan,old.state != .restored,old.state != .cancelled else{throw RestoreFailure.stale};var next=r;if let local=completedIdentifier{guard [.saving,.reconcile].contains(old.state),!local.isEmpty else{throw RestoreFailure.ambiguousSave};next.state = .restored;next.localIdentifier=local}else{guard next.state != .restored,old.state.allows(next.state) else{throw RestoreFailure.stale}};next.revision+=1;let s=try stmt("UPDATE compound SET state=?,revision=?,record=? WHERE id=? AND revision=?");defer{sqlite3_finalize(s)};bind(next.state.rawValue,s,1);sqlite3_bind_int(s,2,Int32(next.revision));try data(next,s,3);bind(next.id.uuidString,s,4);sqlite3_bind_int(s,5,Int32(r.revision));guard sqlite3_step(s)==SQLITE_DONE,sqlite3_changes(db)==1 else{throw RestoreFailure.stale};return next}
}
